import fs from 'fs/promises'
import path from 'path'
import { toggleNotifications } from './actions'

const dataFilePath = path.join(process.cwd(), 'app/data.json')

async function getNotificationStatus() {
  try {
    const fileContent = await fs.readFile(dataFilePath, 'utf-8')
    const data = JSON.parse(fileContent)
    return data.notificationsEnabled
  } catch (error) {
    console.error('Failed to read notification status:', error)
    return false
  }
}

export default async function Home() {
  const isEnabled = await getNotificationStatus()

  return (
    <main className="p-4">
      <h1 className="text-2xl font-bold mb-4">Settings</h1>
      <div className="flex items-center gap-4">
        <p>Notifications are currently: <strong>{isEnabled ? 'ON' : 'OFF'}</strong></p>

        <form action={toggleNotifications}>
          <button 
            type="submit"
            className={`px-4 py-2 rounded ${
              isEnabled 
                ? 'bg-red-500 hover:bg-red-600 text-white' 
                : 'bg-green-500 hover:bg-green-600 text-white'
            }`}
          >
            Turn {isEnabled ? 'Off' : 'On'}
          </button>
        </form>
      </div>
    </main>
  );
}

